DATA = "entials across write, replace, restart and delete', async () => {\n+    const credentials = new Map<string, string>();\n+    const operations: string[] = [];\n+    const native = async (action: 'probe' | 'set' | 'get' | 'delete', id?: string, secret?: string) => {\n+      if (id) operations.push(`${action}:${id}`); // logical OS target, never a file path\n+      if (action === 'set') { credentials.set(id!, secret!); return { ok: true as const }; }\n+      if (action === 'get') return { ok: true as const, secret: credentials.get(id!) ?? null };\n+      if (action === 'delete') return { ok: true as const, deleted: credentials.delete(id!) };\n+      return { ok: true as const };\n+    };\n+    const first = new WindowsCredentialManagerBackend(native);\n+    await first.set('byok-provider-one', 'one-界');\n+    await first.set('byok-provider-two', 'two-ü');\n+    const restarted = new WindowsCredentialManagerBackend(native);\n+    expect(await restarted.get('byok-provider-one')).toBe('one-界');\n+    expect(await restarted.get('byok-provider-two')).toBe('two-ü');\n+    await restarted.set('byok-provider-one', 'replacement');\n+    expect(await restarted.get('byok-provider-two')).toBe('two-ü');\n+    expect(await restarted.delete('byok-provider-one')).toBe(true);\n+    expect(await restarted.get('byok-provider-one')).toBeNull();\n+    expect(await restarted.get('byok-provider-two')).toBe('two-ü');\n+    expect(operations).toContain('set:byok-provider-one');\n+    expect(operations).toContain('set:byok-provider-two');\n+  });\n+\n+  it('keeps new credential filesystem path provenance independent of both valid IDs', () => {\n+    // The native credential backend must perform ZERO file operations. Logical\n+    // IDs are CredMan target names, not filesystem names or hash-derived paths.\n+    const source = readFileSync(new URL('../../src/byok/windows-credential-manager.ts', import.meta.url), 'utf8');\n+    const sinkPattern = /\\b(?:readFile|writeFile|rename|unlink|mkdir|open|createWriteStream|createReadStream|mkdtemp)\\s*\\(/g;\n+    const newPathsFor = (_id: string) => [...source.matchAll(sinkPattern)].map((match) => match[0]);\n+    expect(newPathsFor('byok-provider-one')).toEqual([]);\n+    expect(newPathsFor('byok-provider-two')).toEqual(newPathsFor('byok-provider-one'));\n+    expect(source).toContain(\"$target = 'dev.opendesign.byok:' + $id\");\n+  });\n+});\n"
